325: { es: 'Hace 10 de daño más 10 por cada Energía Agua en tu pila de descartes. Luego baraja todas las Energías Agua de tu descarte en tu mazo.', f: async x => { const w = x.me.discard.filter(c => x.g.def(c).name === 'Water Energy'); x.dmg = 10 + 10 * w.length; x.post(() => { for (const c of w) x.g.removeFrom(x.me.discard, c); shuffleIntoDeck(x.g, x.me, w); }); } },
326: { es: 'Hace 10 de daño por cada Energía unida al Pokémon Defensor. Después, retira de {S} tantos contadores de daño como el daño hecho al Defensor.', f: async x => { x.dmg = 10 * (x.def ? x.g.energyCount(x.def) : 0); x.post(() => { if (x.dealtMain) x.heal(x.att, x.dealtMain); }); } },
327: { es: 'Hace 10 de daño a cada Pokémon en juego que no sea Lucha. Sin aplicar Debilidad ni Resistencia.', f: async x => { x.dmg = 0; for (const s of x.g.allSlots()) if (!x.g.eff(s).types.includes('F')) x.dmgTo(s, 10); } },
328: { es: 'Hace 10 de daño a cada Pokémon de tu rival por cada carta de Energía unida a ese Pokémon. Sin aplicar Debilidad ni Resistencia.', f: async x => { x.dmg = 0; for (const s of x.g.slots(x.op)) if (s.energy.length) x.dmgTo(s, 10 * s.energy.length); } },
329: { es: 'Hace 20 de daño a cada Pokémon en juego que tenga un Poder Pokémon. Sin aplicar Debilidad ni Resistencia.', f: async x => { x.dmg = 0; for (const s of x.g.allSlots()) if (x.g.baseDef(s).pw) x.dmgTo(s, 20); } },
330: { es: 'Hace 30 de daño más 10 por cada carta de Energía unida al Pokémon Defensor.', f: async x => { x.dmg = 30 + 10 * (x.def ? x.def.energy.length : 0); } },
331: { es: 'Hace 30 de daño por cada carta con {S} en su nombre que tengas en juego (incluido este).', f: async x => { const n = x.g.slots(x.me).filter(s => x.g.eff(s).name.indexOf(x.e.name.replace(/^(Dark|Light|Shining) /, '')) >= 0).length; x.dmg = 30 * Math.max(1, n); } },
332: { es: 'Hace 50 de daño más 10 por cada Energía Agua unida a {S} que no se use para pagar el coste del ataque. No se aplica Resistencia.', f: async x => { x.dmg += 10 * x.g.extraEnergy(x.att, x.atk, 'W'); x.res = false; } },
333: { es: 'Hace un daño igual a la mitad de los PS restantes del Pokémon Defensor (redondeado hacia abajo a la decena).', f: async x => { x.dmg = x.def ? floor10(x.g.hpLeft(x.def) / 2) : 0; } },
