351: { es: 'Lanza 3 monedas. Por cada cara, pon 1 contador de daño en el Pokémon Defensor.', f: async x => { const h = await x.flip(3); x.post(() => { if (x.def && x.g.allSlots().includes(x.def) && !x.immune.has(x.def.u) && !x.def.fx.immune) { x.def.dmg += 10 * h; if (h) x.log(`Pone ${h} contador(es) en ${x.g.nm(x.def)}.`); } }); } },
