def('[Engage]', { es: 'Cuando juegues a {S} desde tu mano, tu rival puede barajar su mano en su mazo y robar 4 cartas. Luego tú puedes hacer lo mismo.', onPlay: async (g, p) => { for (const pl of [g.opp(p), p]) { if (!(await g.ask(pl, { kind: 'yesno', title: '[Enfrentar]: ¿barajar tu mano y robar 4?', purpose: 'engage' }))) continue; pl.deck.push(...pl.hand); pl.hand = []; g.shuffleDeck(pl); g.draw(pl, 4); g.log(`${pl.name} baraja su mano y roba 4.`); } } });
def('[Increase]', { es: 'Cuando juegues a {S} desde tu mano, puedes buscar en tu mazo una carta con Unown en su nombre y ponerla en tu Banca. Baraja tu mazo después.', onPlay: async (g, p) => { await benchFromDeck(g, p, d => d.st === 'P' && d.name.indexOf('Unown') === 0, '[Aumentar]: elige un Unown'); } });
def('[Vanish]', { es: 'Cuando juegues a {S} desde tu mano, puedes lanzar una moneda. Si sale cara, devuelve a tu mano 1 de tus Pokémon con Unown en su nombre (distinto de {S}). Descarta sus cartas unidas.', onPlay: async (g, p, s) => { const ts = g.slots(p).filter(t => t !== s && isUnown(g, t)); if (!ts.length || !(await g.flip(p, 1, '[Desvanecer]'))[0]) return; const t = await g.ask(p, { kind: 'slot', title: 'Elige un Unown para devolver a tu mano', options: ts, purpose: 'own' }); const z = t || ts[0]; const wa = p.active === z; g.removeSlot(z); p.hand.push(...z.cards); for (const c of z.energy.concat(z.att)) g.toDiscard(c); if (wa) await newActive(g, p); } });
def('Howl', { es: 'Cuando juegues a {S} desde tu mano, puedes descartar las 5 cartas superiores de tu mazo. Une las Energías Fuego que haya entre ellas a tus Pokémon Fuego. Usar este poder termina tu turno.', onPlay: async (g, p) => { if (!(await g.ask(p, { kind: 'yesno', title: '¿Usar Aullido? (termina tu turno)', purpose: 'howl' }))) return; const top = p.deck.splice(-5); const fire = top.filter(c => g.def(c).name === 'Fire Energy'); const ts = g.slots(p).filter(s => g.eff(s).types.includes('R')); for (const c of top) if (!fire.includes(c) || !ts.length) g.toDiscard(c); for (const c of fire) if (ts.length) { const t = ts.length === 1 ? ts[0] : await g.ask(p, { kind: 'slot', title: 'Aullido: ¿a quién unes esta Energía Fuego?', options: ts, purpose: 'energyTarget' }); c.inPlay = true; (t || ts[0]).energy.push(c); } g.log(`Aullido une ${fire.length} Energía(s) Fuego. El turno termina.`); p.turnOver = true; p.forceEnd = true; } });
