const once = true;
def('Cunning', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, mira la carta superior del mazo de tu rival. Luego puedes hacer que tu rival baraje su mazo.' + NB, once, use: async (g, p) => { if (!(await g.flip(p, 1, 'Astucia'))[0]) return; const o = g.opp(p); const c = o.deck[o.deck.length - 1]; if (!c) return; await show(g, p, [c], 'Carta superior del rival'); if (g.isTrainer(c) || g.def(c).st === 'P') { if (await g.ask(p, { kind: 'yesno', title: '¿Hacer que tu rival baraje su mazo?', purpose: 'yes' })) g.shuffleDeck(o); } }, ai: () => false });
