def('Drive Off', { es: 'Mientras {S} sea tu Pokémon Activo, una vez durante tu turno (antes de atacar), si tu rival tiene Pokémon en Banca, él elige 1 y lo cambia por el Defensor.' + NB, once, can: (g, p, s) => p.active === s && g.opp(p).bench.length > 0, use: async (g, p) => { const o = g.opp(p); const t = await g.ask(o, { kind: 'slot', title: 'Ahuyentar: elige tu nuevo Pokémon Activo', options: o.bench.slice(), purpose: 'newActive' }); await g.switchActive(o, t || o.bench[0]); }, ai: (g, p) => { const o = g.opp(p); return o.active && (g.energyCount(o.active) >= 2 || o.active.st); } });
def('Electromagnetic Power', { es: 'Tantas veces como quieras durante tu turno (antes de atacar), puedes pasar 1 Energía de uno de tus Magnemite, {S} o {S} Oscuro a otro de ellos.' + NB, can: (g, p) => { const m = g.slots(p).filter(s => /Magnemite|Magneton/.test(g.eff(s).name)); return m.length > 1 && m.some(s => s.energy.length); }, use: async (g, p) => { const m = g.slots(p).filter(s => /Magnemite|Magneton/.test(g.eff(s).name)); const from = await g.ask(p, { kind: 'slot', title: 'Elige de dónde mover la Energía', options: m.filter(s => s.energy.length), purpose: 'energyFrom' }); const to = await g.ask(p, { kind: 'slot', title: 'Elige a dónde moverla', options: m.filter(s => s !== from), purpose: 'energyTarget' }); const [c] = await g.ask(p, { kind: 'cards', title: 'Elige la Energía', cards: from.energy.slice(), min: 1, max: 1, purpose: 'payOwnEnergy' }); g.removeFrom(from.energy, c); to.energy.push(c); g.log(`Mueve ${g.cn(c)} a ${g.nm(to)}.`); }, ai: () => false });
def('Energy Converter', { es: 'Una vez durante tu turno (antes de atacar), puedes elegir 1 Energía básica unida a uno de tus Pokémon y un tipo de Energía. Esa Energía cuenta como ese tipo hasta el final de tu turno.' + NB, once, can: (g, p) => g.slots(p).some(s => s.energy.some(c => g.isBasicEnergy(c))), use: async (g, p) => { const z = g.slots(p).flatMap(s => s.energy.filter(c => g.isBasicEnergy(c)).map(c => [s, c])); const [c] = await g.ask(p, { kind: 'cards', title: 'Elige una Energía básica', cards: z.map(q => q[1]), min: 1, max: 1, purpose: 'payOwnEnergy' }); const ty = await g.ask(p, { kind: 'type', title: 'Elige el nuevo tipo', exclude: ['C'], purpose: 'resType' }); c.conv = ty; c.convT = g.turnNo; g.log(`${g.cn(c)} cuenta como Energía ${T[ty]} este turno.`); }, ai: () => false });
def('Fire Recharge', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, une una Energía Fuego de tu pila de descartes a uno de tus Pokémon Fuego.' + NB, once, can: (g, p) => p.discard.some(c => g.def(c).name === 'Fire Energy'), use: async (g, p) => { if (!(await g.flip(p, 1, 'Recarga de Fuego'))[0]) return; const c = p.discard.find(c => g.def(c).name === 'Fire Energy'); const ts = g.slots(p).filter(s => g.eff(s).types.includes('R')); if (!ts.length) return; const t = await g.ask(p, { kind: 'slot', title: 'Recarga de Fuego: elige un Pokémon Fuego', options: ts, purpose: 'energyTarget' }); g.removeFrom(p.discard, c); c.inPlay = true; (t || ts[0]).energy.push(c); g.log(`Une una Energía Fuego a ${g.nm(t || ts[0])}.`); }, ai: () => true });
def('Gaze', { es: 'Una vez durante tu turno (antes de atacar), elige 1 Pokémon en Banca de tu rival con un Poder Pokémon. Ese poder deja de funcionar hasta el final del turno.', once, can: (g, p) => g.opp(p).bench.some(s => g.baseDef(s).pw), use: async (g, p) => { const ts = g.opp(p).bench.filter(s => g.baseDef(s).pw); const t = await g.ask(p, { kind: 'slot', title: 'Mirada: elige un Pokémon', options: ts, purpose: 'damageOpp' }); (t || ts[0]).fx.powerOff = { v: true, until: g.turnNo }; g.log(`El poder de ${g.nm(t || ts[0])} se anula este turno.`); }, ai: () => false });
def('Glaring Gaze', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, mira la mano de tu rival. Si tiene Entrenadores, elige 1 y tu rival lo baraja en su mazo.' + NB, once, can: (g, p) => g.opp(p).hand.length > 0, use: async (g, p) => { if (!(await g.flip(p, 1, 'Mirada Penetrante'))[0]) return; const o = g.opp(p); await show(g, p, o.hand.slice(), 'Mano del rival'); const tr = o.hand.filter(c => g.isTrainer(c)); if (!tr.length) return; const [c] = await g.ask(p, { kind: 'cards', title: 'Elige un Entrenador', cards: tr, min: 1, max: 1, purpose: 'default' }); g.removeFrom(o.hand, c); o.deck.push(c); g.shuffleDeck(o); g.log(`${g.cn(c)} vuelve al mazo del rival.`); }, ai: () => true });
def('Playful Punch', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, haz 20 de daño al Pokémon Activo de tu rival (aplica Debilidad y Resistencia). En cualquier caso, tu turno termina.' + NB, once, can: (g, p) => !!g.opp(p).active, use: async (g, p, s) => { const o = g.opp(p); if ((await g.flip(p, 1, 'Puñetazo Juguetón'))[0] && o.active) { const x = g.mkCtx(p, s, { dmg: '20', name: 'Playful Punch', cost: [] }, g.eff(s)); const d = g.attackDamage(x, o.active, 20, { wr: true }); g.log(`Puñetazo Juguetón hace ${d} de daño.`); } g.log('El turno termina.'); p.turnOver = true; p.forceEnd = true; }, ai: () => false });
def('Revive Fossil', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, busca en tu mazo una carta que evolucione de Fósil Misterioso y ponla en tu Banca como Pokémon Básico. Baraja tu mazo después.' + NB, once, can: (g, p) => room(g, p), use: async (g, p) => { if (!(await g.flip(p, 1, 'Revivir Fósil'))[0]) return; await benchFromDeck(g, p, d => d.from === 'Mysterious Fossil', 'Elige un Pokémon Fósil', true); }, ai: (g, p) => p.deck.some(c => g.def(c).from === 'Mysterious Fossil') });
def('Revive Friends', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, busca en tu mazo una carta llamada {S} y ponla en tu Banca como Pokémon Básico. Baraja tu mazo después.' + NB, once, can: (g, p) => room(g, p), use: async (g, p, s) => { if (!(await g.flip(p, 1, 'Revivir Amigos'))[0]) return; const n = g.eff(s).name; await benchFromDeck(g, p, d => d.name === n, `Elige un ${n}`, true); }, ai: (g, p, s) => p.deck.some(c => g.def(c).name === g.eff(s).name) });
def('Spatial Distortion', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, pon en juego un Estadio de tu pila de descartes (descarta el que haya en juego).' + NB, once, can: (g, p) => p.discard.some(c => (g.def(c).sub || []).includes('Stadium')), use: async (g, p) => { if (!(await g.flip(p, 1, 'Distorsión Espacial'))[0]) return; const opts = p.discard.filter(c => (g.def(c).sub || []).includes('Stadium')); const [c] = await g.ask(p, { kind: 'cards', title: 'Elige un Estadio', cards: opts, min: 1, max: 1, purpose: 'getAny' }); g.removeFrom(p.discard, c); if (g.stadium) g.toDiscard(g.stadium); g.stadium = c; g.log(`${g.cn(c)} entra en juego.`); }, ai: () => true });
def('Submerge', { es: 'Una vez durante tu turno (antes de atacar), puedes cambiar el tipo de {S} a Agua hasta el final del turno.' + NB, once, use: async (g, p, s) => { s.fx.submerge = { v: true, until: g.turnNo }; g.log(`${g.nm(s)} pasa a ser de tipo Agua este turno.`); }, ai: (g, p, s) => { const o = g.opp(p); return p.active === s && o.active && g.eff(o.active).weak === 'W'; } });
def('[Bear]', { es: 'Una vez durante tu turno (antes de atacar), puedes mover 1 contador de daño de uno de tus Pokémon con Unown en su nombre a {S}. No puede usarse si a {S} le quedan 10 PS.' + AW, once, ignoreStatus: true, can: (g, p, s) => g.hpLeft(s) > 10 && g.slots(p).some(t => t !== s && isUnown(g, t) && t.dmg > 0), use: async (g, p, s) => { const ts = g.slots(p).filter(t => t !== s && isUnown(g, t) && t.dmg > 0); const t = await g.ask(p, { kind: 'slot', title: 'Elige el Unown del que quitar 1 contador', options: ts, purpose: 'healOwn' }); (t || ts[0]).dmg -= 10; s.dmg += 10; }, ai: () => false });
def('[Find]', { es: 'Una vez durante tu turno (antes de atacar), si tienes a {S}, Unown [I], Unown [N] y Unown [D] en tu Banca, puedes buscar en tu mazo un Entrenador y ponerlo en tu mano. Baraja tu mazo después.', once, can: (g, p) => benchHas(g, p, ['F', 'I', 'N', 'D']), use: async (g, p) => { const opts = p.deck.filter(c => g.isTrainer(c)); if (opts.length) { const [c] = await g.ask(p, { kind: 'cards', title: 'Elige un Entrenador', cards: opts, min: 0, max: 1, purpose: 'getAny', fromDeck: true }); if (c) { g.removeFrom(p.deck, c); p.hand.push(c); } } g.shuffleDeck(p); }, ai: () => true });
def('[Give]', { es: 'Una vez durante tu turno (antes de atacar), si tienes a {S}, Unown [I], Unown [V] y Unown [E] en tu Banca, puedes lanzar una moneda. Si sale cara, busca en tu mazo una Energía básica y únela a uno de tus Pokémon.', once, can: (g, p) => benchHas(g, p, ['G', 'I', 'V', 'E']), use: async (g, p) => { if (!(await g.flip(p, 1, '[Dar]'))[0]) return; const c = p.deck.find(c => g.isBasicEnergy(c)); if (!c) return; const t = await g.ask(p, { kind: 'slot', title: 'Elige a qué Pokémon unirla', options: g.slots(p), purpose: 'energyTarget' }); g.removeFrom(p.deck, c); c.inPlay = true; (t || p.active).energy.push(c); g.shuffleDeck(p); }, ai: () => true });
def('[Help]', { es: 'Una vez durante tu turno (antes de atacar), si tienes a {S}, Unown [E], Unown [L] y Unown [P] en tu Banca, puedes barajar tu mano en tu mazo y robar el mismo número de cartas.', once, can: (g, p) => benchHas(g, p, ['H', 'E', 'L', 'P']), use: async (g, p) => { const n = p.hand.length; p.deck.push(...p.hand); p.hand = []; g.shuffleDeck(p); g.draw(p, n); }, ai: () => false });
