def('[Quicken]', { es: 'Una vez durante tu turno (antes de atacar), puedes lanzar una moneda. Si sale cara, evita todos los efectos de ataques, incluido el daño, hechos a tus Pokémon con Unown en su nombre durante el próximo turno de tu rival.' + AW, once, ignoreStatus: true, can: (g, p) => !p.used.quicken, use: async (g, p) => { p.used.quicken = true; if (!(await g.flip(p, 1, '[Acelerar]'))[0]) return; for (const s of g.slots(p)) if (isUnown(g, s)) { s.fx.immune = { v: true, until: g.turnNo + 1 }; g.noteFx(s, 'immune', true); } }, ai: () => true });
