def('EXP.ALL', { tool: true, es: TOOL + 'Durante el turno rival, si tu Pokémon Activo fuera a quedar Fuera de Combate por un ataque, puedes pasar 1 Energía básica de él al Pokémon con Repartir Exp. y descartar Repartir Exp.', play: async () => 'attached', ai: () => 3 });
