def('Broken Ground Gym', { stadium: true, es: 'Cada jugador paga 1 Energía Incolora más para retirar a un Pokémon Bebé o Básico.' + STAD, ai: () => 2 });
def('Ecogym', { stadium: true, es: 'Cada vez que un ataque, Poder Pokémon o Entrenador descarta una Energía no Incolora de un Pokémon de otro jugador, esa Energía vuelve a la mano de su dueño (no cuenta al quedar Fuera de Combate).' + STAD, ai: () => 2 });
def('Energy Stadium', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador (antes de atacar), puede lanzar una moneda. Si sale cara, pone una Energía básica de su descarte en su mano.' + STAD, actionCan: (g, p) => p.discard.some(c => g.isBasicEnergy(c)), action: async (g, p) => { if (!(await g.flip(p, 1, 'Estadio de Energía'))[0]) return; const opts = p.discard.filter(c => g.isBasicEnergy(c)); const [c] = await g.ask(p, { kind: 'cards', title: 'Elige una Energía básica', cards: opts, min: 1, max: 1, purpose: 'getEnergy' }); g.removeFrom(p.discard, c); p.hand.push(c); }, ai: () => 3 });
def('Healing Field', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador, puede lanzar una moneda. Si sale cara, retira 2 contadores de daño de su Pokémon Activo.' + STAD, actionCan: (g, p) => p.active && p.active.dmg > 0, action: async (g, p) => { if ((await g.flip(p, 1, 'Campo Curativo'))[0]) g.heal(p.active, 20); }, ai: () => 3 });
def('Lucky Stadium', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador (antes de atacar), puede lanzar una moneda. Si sale cara, roba una carta.' + STAD, actionCan: (g, p) => p.deck.length > 1, action: async (g, p) => { if ((await g.flip(p, 1, 'Estadio de la Suerte'))[0]) g.draw(p, 1); }, ai: () => 3 });
def('Radio Tower', { stadium: true, once: true, es: 'Una vez durante el turno de cada jugador (antes de atacar), puede mirar las 2 cartas superiores de su mazo y devolverlas en el mismo orden.' + STAD, actionCan: (g, p) => !p.ai && p.deck.length > 0, action: async (g, p) => { await show(g, p, p.deck.slice(-2).reverse(), 'Torre Radio: tus 2 cartas superiores'); }, ai: () => 1 });
def("Rocket's Hideout", { stadium: true, es: 'Cada Pokémon en juego con "Dark" en su nombre (también los del rival) tiene +20 PS.' + STAD, ai: (g, p) => g.slots(p).some(s => g.eff(s).name.indexOf('Dark ') === 0) ? 6 : 0 });
def('Sprout Tower', { stadium: true, es: 'Todo el daño hecho por ataques de Pokémon Incoloros se reduce en 30 (después de Debilidad y Resistencia).' + STAD, ai: (g, p) => { const o = g.opp(p); return o.active && g.eff(o.active).types.includes('C') ? 5 : 0; } });
// --- Entrenadores normales ---
def('Arcade Game', { es: 'Baraja tu mazo y enseña las 3 cartas superiores. Si al menos 2 tienen el mismo nombre, pon todas las de ese nombre en tu mano y baraja el resto en tu mazo. Si no, baraja las 3 en tu mazo.', can: (g, p) => p.deck.length >= 3, play: async (g, p) => { g.shuffleDeck(p); const top = p.deck.slice(-3); g.log('Juego Arcade: ' + top.map(c => g.cn(c)).join(', ')); const names = {}; for (const c of top) names[g.def(c).name] = (names[g.def(c).name] || 0) + 1; const n = Object.keys(names).find(k => names[k] >= 2); if (n) for (const c of top.filter(c => g.def(c).name === n)) { g.removeFrom(p.deck, c); p.hand.push(c); } g.shuffleDeck(p); }, ai: () => 2 });
def("Bill's Teleporter", { es: 'Lanza una moneda. Si sale cara, roba 4 cartas.', play: async (g, p) => { if ((await g.flip(p, 1, 'Teletransportador de Bill'))[0]) g.draw(p, 4); }, ai: (g, p) => p.deck.length > 8 ? 7 : 0 });
def('Card-Flip Game', { es: 'Elige 1 de los Premios boca abajo de tu rival y adivina si es Energía, Entrenador o Pokémon. Dale la vuelta (queda boca arriba). Si aciertas, roba 2 cartas.', can: (g, p) => g.opp(p).prizes.length > 0, play: async (g, p) => { const o = g.opp(p); const c = o.prizes[Math.floor(g.rnd() * o.prizes.length)]; const guess = await g.ask(p, { kind: 'option', title: 'Juego de Voltear Cartas: ¿qué es?', options: ['Energía', 'Entrenador', 'Pokémon'], purpose: 'quizGuess' }); const cat = g.isEnergy(c) ? 0 : g.isTrainer(c) ? 1 : 2; c.faceUp = true; g.log(`El Premio es ${g.cn(c)}: ${guess === cat ? 'acierta' : 'falla'}.`); if (guess === cat) g.draw(p, 2); }, ai: () => 2 });
def('Double Gust', { es: 'Si tienes Pokémon en Banca, tu rival elige 1 y lo cambia por tu Pokémon Activo. Luego, si tu rival tiene Pokémon en Banca, elige 1 y cámbialo por su Pokémon Activo.', can: (g, p) => g.opp(p).bench.length > 0, play: async (g, p) => { const o = g.opp(p); if (p.bench.length) { const t = await g.ask(o, { kind: 'slot', title: 'Doble Ráfaga: elige el nuevo Activo de tu rival', options: p.bench.slice(), purpose: 'narrow' }); await g.switchActive(p, t || p.bench[0]); } const t2 = await g.ask(p, { kind: 'slot', title: 'Doble Ráfaga: elige el nuevo Activo rival', options: o.bench.slice(), purpose: 'gustTarget' }); await g.switchActive(o, t2 || o.bench[0]); }, ai: () => 0 });
def('Energy Amplifier', { es: 'Elige una Energía de tu mano, enséñala y barájala en tu mazo. Luego lanza una moneda. Si sale cara, busca en tu mazo hasta 3 Energías básicas y ponlas en tu mano. Baraja tu mazo después.', can: (g, p, c) => others(p, c).some(x => g.isEnergy(x)), play: async (g, p, c) => { const en = others(p, c).filter(x => g.isEnergy(x)); const [e] = await g.ask(p, { kind: 'cards', title: 'Elige una Energía para barajar en tu mazo', cards: en, min: 1, max: 1, purpose: 'discardHand' }); g.removeFrom(p.hand, e); p.deck.push(e); g.shuffleDeck(p); if ((await g.flip(p, 1, 'Amplificador de Energía'))[0]) await toHandFromDeck(g, p, x => g.isBasicEnergy(x), 3, 'Elige hasta 3 Energías básicas'); }, ai: () => 4 });
def('Energy Ark', { es: 'Lanza 2 monedas. Por cada cara, busca en tu mazo una Energía básica, enséñala y ponla en tu mano. Baraja tu mazo después.', play: async (g, p) => { const h = await g.flipHeads(p, 2, 'Arca de Energía'); if (h) await toHandFromDeck(g, p, x => g.isBasicEnergy(x), h, `Elige hasta ${h} Energías básicas`); else g.shuffleDeck(p); }, ai: (g, p) => p.hand.some(c => g.isEnergy(c)) ? 2 : 6 });
def('Energy Charge', { es: 'Lanza una moneda. Si sale cara, baraja hasta 2 cartas de Energía de tu pila de descartes en tu mazo.', can: (g, p) => p.discard.some(c => g.isEnergy(c)), play: async (g, p) => { if (!(await g.flip(p, 1, 'Carga de Energía'))[0]) return; const opts = p.discard.filter(c => g.isEnergy(c)); const sel = await g.ask(p, { kind: 'cards', title: 'Elige hasta 2 Energías', cards: opts, min: 0, max: Math.min(2, opts.length), purpose: 'getEnergy' }); for (const c of sel) { g.removeFrom(p.discard, c); p.deck.push(c); } g.shuffleDeck(p); }, ai: (g, p) => p.deck.length < 15 ? 3 : 1 });
def('Fossil Egg', { es: 'Lanza una moneda. Si sale cara, busca en tu mazo (o en tu mano) una carta que evolucione de Fósil Misterioso y ponla en tu Banca como Pokémon Básico. (No puedes jugarla si tu Banca está llena.)', can: (g, p) => room(g, p), play: async (g, p, c) => { if (!(await g.flip(p, 1, 'Huevo Fósil'))[0]) return; const opts = p.deck.concat(others(p, c)).filter(x => g.def(x).from === 'Mysterious Fossil'); if (!opts.length) { g.shuffleDeck(p); return; } const [x] = await g.ask(p, { kind: 'cards', title: 'Elige un Pokémon Fósil', cards: opts, min: 1, max: 1, purpose: 'searchBasic', fromDeck: true }); if (p.deck.includes(x)) g.removeFrom(p.deck, x); else g.removeFrom(p.hand, x); p.bench.push(g.mkSlot(p, x)); g.shuffleDeck(p); g.log(`${g.cn(x)} entra en la Banca como Pokémon Básico.`); }, ai: (g, p) => p.deck.some(c => g.def(c).from === 'Mysterious Fossil') ? 6 : 0 });
def('Heal Powder', { es: 'Lanza una moneda. Si sale cara, tu Pokémon Activo deja de estar Dormido, Confundido, Paralizado o Envenenado y retira 2 contadores de daño de él.', can: (g, p) => p.active && (p.active.dmg > 0 || p.active.st || p.active.poison), play: async (g, p) => { if ((await g.flip(p, 1, 'Polvo Curación'))[0]) { g.cure(p.active); g.heal(p.active, 20); g.log('Polvo Curación cura al Pokémon Activo.'); } }, ai: (g, p) => (p.active.st || p.active.poison) ? 6 : p.active.dmg >= 20 ? 4 : 0 });
def('Hyper Devolution Spray', { es: 'Elige 1 de tus Pokémon evolucionados. Pon su carta de Evolución de mayor Fase en tu mano. (No puedes evolucionar ese Pokémon este turno.)', can: (g, p) => g.slots(p).some(s => s.cards.length > 1), play: async (g, p) => { const ts = g.slots(p).filter(s => s.cards.length > 1); const t = await g.ask(p, { kind: 'slot', title: 'Elige un Pokémon evolucionado', options: ts, purpose: 'scoopDamaged' }); const s = t || ts[0]; const c = s.cards.pop(); p.hand.push(c); s.evolved = g.turnNo; s.fx = {}; g.log(`${g.cn(c)} vuelve a la mano.`); }, ai: () => 0 });
def("Impostor Professor Oak's Invention", { es: 'Mira las cartas de Premio de tu rival. Puedes hacer que las baraje en su mazo; si lo hace, pone esa misma cantidad de cartas superiores de su mazo como nuevos Premios (sin mirarlas).', can: (g, p) => g.opp(p).prizes.length > 0, play: async (g, p) => { const o = g.opp(p); await show(g, p, o.prizes.slice(), 'Premios del rival'); if (await g.ask(p, { kind: 'yesno', title: '¿Barajar sus Premios en su mazo?', purpose: 'impostor' })) { const n = o.prizes.length; o.deck.push(...o.prizes); o.prizes = []; g.shuffleDeck(o); for (let i = 0; i < n && o.deck.length; i++) o.prizes.push(o.deck.pop()); g.log('Los Premios del rival se renuevan.'); } }, ai: () => 0 });
def('Magnifier', { es: 'Une la Lupa a 1 de tus Pokémon. Al final de tu turno, descártala. Si ese Pokémon ataca, no se aplica Resistencia en ese ataque.', play: async (g, p, c) => { const t = await g.ask(p, { kind: 'slot', title: '¿A qué Pokémon unes la Lupa?', options: g.slots(p), purpose: 'attachTool' }); (t || p.active).att.push(c); return 'attached'; }, ai: (g, p) => { const o = g.opp(p); return p.active && o.active && g.eff(o.active).res && g.eff(p.active).types.includes(g.eff(o.active).res) ? 6 : 0; } });
def('Mail from Bill', { es: 'No puedes jugar esta carta si tienes 5 o más cartas en tu mano (incluida esta). Roba cartas hasta tener exactamente 4 en tu mano.', can: (g, p) => p.hand.length <= 4, play: async (g, p) => { g.draw(p, Math.max(0, 4 - p.hand.length)); }, ai: (g, p) => p.hand.length <= 2 ? 8 : 0 });
def('Mary', { es: 'Roba 2 cartas. Luego baraja 2 cartas de tu mano en tu mazo.', play: async (g, p) => { g.draw(p, 2); const n = Math.min(2, p.hand.length); if (!n) return; const sel = await g.ask(p, { kind: 'cards', title: 'Mary: elige 2 cartas para barajar en tu mazo', cards: p.hand.slice(), min: n, max: n, purpose: 'discardHand' }); for (const c of sel) { g.removeFrom(p.hand, c); p.deck.push(c); } g.shuffleDeck(p); }, ai: () => 4 });
def('Moo-Moo Milk', { es: 'Elige 1 de tus Pokémon. Lanza 2 monedas. Retira 2 contadores de daño de ese Pokémon por cada cara.', can: (g, p) => g.slots(p).some(s => s.dmg > 0), play: async (g, p) => { const ts = g.slots(p).filter(s => s.dmg > 0); const t = await g.ask(p, { kind: 'slot', title: 'Leche Mu-mu: elige un Pokémon', options: ts, purpose: 'healOwn' }); const h = await g.flipHeads(p, 2, 'Leche Mu-mu'); g.heal(t || ts[0], 20 * h); }, ai: (g, p) => p.active && p.active.dmg >= 30 ? 5 : 0 });
def('New Pokédex', { es: 'Baraja tu mazo. Luego mira hasta 5 cartas de la parte superior y reordénalas como quieras.', play: async (g, p) => { g.shuffleDeck(p); const top = p.deck.slice(-5).reverse(); if (!top.length) return; const ord = await g.ask(p, { kind: 'order', title: 'Nueva Pokédex: reordena (la primera quedará arriba)', cards: top, purpose: 'orderOwn' }); p.deck.splice(p.deck.length - top.length, top.length, ...(ord || top).slice().reverse()); }, ai: () => 1 });
def('Old Rod', { es: 'Lanza 2 monedas. Si ambas salen cara, pon un Pokémon de tu descarte en tu mano. Si ambas salen cruz, pon un Entrenador de tu descarte en tu mano.', can: (g, p) => p.discard.length > 0, play: async (g, p) => { const r = await g.flip(p, 2, 'Caña Vieja'); const h = r.filter(v => v).length; const pred = h === 2 ? (c => isPk(g, c)) : h === 0 ? (c => g.isTrainer(c)) : null; if (!pred) return; const opts = p.discard.filter(pred); if (!opts.length) return; const [c] = await g.ask(p, { kind: 'cards', title: 'Elige una carta de tu descarte', cards: opts, min: 1, max: 1, purpose: 'getAny' }); g.removeFrom(p.discard, c); p.hand.push(c); }, ai: () => 1 });
def('PokéGear', { es: 'Mira las 7 cartas superiores de tu mazo. Si hay Entrenadores, puedes enseñar 1 y ponerlo en tu mano. Baraja tu mazo después. No puedes jugar más Entrenadores este turno.', play: async (g, p) => { const top = p.deck.slice(-7); const tr = top.filter(c => g.isTrainer(c)); if (tr.length) { const [c] = await g.ask(p, { kind: 'cards', title: 'PokéGear: elige un Entrenador', cards: tr, min: 0, max: 1, purpose: 'getAny', fromDeck: true }); if (c) { g.removeFrom(p.deck, c); p.hand.push(c); } } g.shuffleDeck(p); noMore(g, p); }, ai: () => 1 });
def('Pokémon Breeder Fields', { es: 'Lanza una moneda por 1 o 2 de tus Pokémon (no Bebés) que puedan evolucionar. Por cada cara, busca en tu mazo una carta de Fase posterior que corresponda a ese Pokémon y ponla en tu mano. Baraja tu mazo después.', can: (g, p) => g.slots(p).some(s => !g.isBaby(s) && p.deck.some(c => g.def(c).from === g.baseDef(s).name)), play: async (g, p) => { const ts = g.slots(p).filter(s => !g.isBaby(s) && p.deck.some(c => g.def(c).from === g.baseDef(s).name)); const pick = ts.length <= 2 ? ts : await g.ask(p, { kind: 'slots', title: 'Elige 1 o 2 Pokémon', options: ts, min: 1, max: 2, purpose: 'evolveTarget' }); for (const s of pick) { if (!(await g.flip(p, 1, `Campos del Criador: ${g.nm(s)}`))[0]) continue; const n = g.baseDef(s).name; const c = p.deck.find(c => g.def(c).from === n) || p.deck.find(c => { const d = g.def(c); const mid = Object.values(PT.DB).find(m => m.name === d.from); return mid && mid.from === n; }); if (c) { g.removeFrom(p.deck, c); p.hand.push(c); g.log(`${g.cn(c)} va a la mano.`); } } g.shuffleDeck(p); }, ai: () => 6 });
def('Pokémon March', { es: 'Tu rival puede buscar en su mazo 1 Pokémon Básico y ponerlo en su Banca. Luego tú puedes hacer lo mismo. Cada jugador baraja su mazo.', play: async (g, p) => { for (const pl of [g.opp(p), p]) { if (!room(g, pl)) continue; const opts = pl.deck.filter(c => g.isBasicCard(c) && isPk(g, c)); if (opts.length) { const [c] = await g.ask(pl, { kind: 'cards', title: 'Marcha Pokémon: elige un Pokémon Básico', cards: opts, min: 0, max: 1, purpose: 'searchBasic', fromDeck: true }); if (c) { g.removeFrom(pl.deck, c); pl.bench.push(g.mkSlot(pl, c)); g.log(`${pl.name} pone a ${g.cn(c)} en su Banca.`); } } g.shuffleDeck(pl); } }, ai: (g, p) => p.bench.length < 3 ? 5 : 0 });
def('Pokémon Personality Test', { es: 'Pon boca abajo una carta de Evolución de tu mano. Tu rival adivina si tiene "Light" en su nombre, "Dark" o ninguna de las dos. Si acierta, roba 3 cartas; si falla, robas tú 3. La carta vuelve a tu mano.', can: (g, p, c) => others(p, c).some(x => g.isEvoCard(x)), play: async (g, p, c) => { const evo = others(p, c).filter(x => g.isEvoCard(x)); const [e] = await g.ask(p, { kind: 'cards', title: 'Elige una carta de Evolución', cards: evo, min: 1, max: 1, purpose: 'quiz' }); const o = g.opp(p); const ans = await g.ask(o, { kind: 'option', title: 'Test de Personalidad: ¿qué tipo es?', options: ['Luminoso (Light)', 'Oscuro (Dark)', 'Ninguno'], purpose: 'quizGuess' }); const n = g.def(e).name; const cat = n.indexOf('Light ') === 0 ? 0 : n.indexOf('Dark ') === 0 ? 1 : 2; g.log(`La carta era ${g.cn(e)}: el rival ${ans === cat ? 'acierta' : 'falla'}.`); g.draw(ans === cat ? o : p, 3); }, ai: () => 3 });
def('Professor Elm', { es: 'Baraja tu mano en tu mazo. Luego roba 7 cartas. No puedes jugar más Entrenadores este turno.', play: async (g, p, c) => { for (const x of others(p, c)) { g.removeFrom(p.hand, x); p.deck.push(x); } g.shuffleDeck(p); g.draw(p, 7); noMore(g, p); }, ai: (g, p, c) => others(p, c).length <= 3 && p.deck.length > 10 ? 8 : 0 });
def('Ruin Wall', { es: 'Busca en tu mazo una carta con Unown en su nombre y ponla en tu Banca. Baraja tu mazo después. (No puedes jugarla si tu Banca está llena.)', can: (g, p) => room(g, p), play: async (g, p) => { const opts = p.deck.filter(c => isPk(g, c) && g.def(c).name.indexOf('Unown') === 0); if (opts.length) { const [c] = await g.ask(p, { kind: 'cards', title: 'Elige un Unown', cards: opts, min: 0, max: 1, purpose: 'searchBasic', fromDeck: true }); if (c) { g.removeFrom(p.deck, c); p.bench.push(g.mkSlot(p, c)); } } g.shuffleDeck(p); }, ai: (g, p) => p.deck.some(c => g.def(c).name.indexOf('Unown') === 0) ? 6 : 0 });
def('Super Energy Retrieval', { es: 'Descarta 2 de las otras cartas de tu mano para poner en tu mano hasta 4 Energías básicas de tu pila de descartes.', can: (g, p, c) => others(p, c).length >= 2 && p.discard.some(x => g.isBasicEnergy(x)), play: async (g, p, c) => { const sel = await g.ask(p, { kind: 'cards', title: 'Descarta 2 cartas', cards: others(p, c), min: 2, max: 2, purpose: 'discardHand' }); for (const x of sel) { g.removeFrom(p.hand, x); g.toDiscard(x); } const en = p.discard.filter(x => g.isBasicEnergy(x) && !sel.includes(x)).slice(0, 4); for (const x of en) { g.removeFrom(p.discard, x); p.hand.push(x); } g.log(`${p.name} recupera ${en.length} Energías.`); }, ai: (g, p) => p.discard.filter(x => g.isBasicEnergy(x)).length >= 3 ? 5 : 0 });
def('Super Rod', { es: 'Lanza una moneda. Si sale cara, pon una carta de Evolución de tu descarte en tu mano. Si sale cruz, pon un Pokémon Básico de tu descarte en tu mano.', can: (g, p) => p.discard.some(c => isPk(g, c)), play: async (g, p) => { const h = (await g.flip(p, 1, 'Súper Caña'))[0]; const opts = p.discard.filter(c => isPk(g, c) && (h ? g.def(c).stage > 0 : g.def(c).stage === 0)); if (!opts.length) return; const [c] = await g.ask(p, { kind: 'cards', title: 'Elige una carta de tu descarte', cards: opts, min: 1, max: 1, purpose: 'getAny' }); g.removeFrom(p.discard, c); p.hand.push(c); }, ai: () => 2 });
def('Super Scoop Up', { es: 'Lanza una moneda. Si sale cara, devuelve 1 de tus Pokémon y todas sus cartas unidas a tu mano.', can: (g, p) => g.slots(p).length > 1, play: async (g, p) => { if (!(await g.flip(p, 1, 'Súper Recogida'))[0]) return; const t = await g.ask(p, { kind: 'slot', title: 'Elige un Pokémon para devolver a tu mano', options: g.slots(p), purpose: 'scoopDamaged' }); const s = t || p.active; const wa = p.active === s; g.removeSlot(s); p.hand.push(...s.cards, ...s.energy, ...s.att); for (const c of s.energy) delete c.inPlay; if (wa) await newActive(g, p); }, ai: (g, p) => p.active && g.hpLeft(p.active) <= 20 && p.bench.length ? 6 : 0 });
def("Team Rocket's Evil Deeds", { es: 'Mira la mano de tu rival y elige una carta. Tu rival la baraja en su mazo. Luego tu rival puede robar hasta 2 cartas.', can: (g, p) => g.opp(p).hand.length > 0, play: async (g, p) => { const o = g.opp(p); const [c] = await g.ask(p, { kind: 'cards', title: 'Elige una carta de la mano rival', cards: o.hand.slice(), min: 1, max: 1, purpose: 'default' }); g.removeFrom(o.hand, c); o.deck.push(c); g.shuffleDeck(o); g.log(`${g.cn(c)} vuelve al mazo del rival.`); if (await g.ask(o, { kind: 'yesno', title: '¿Robar 2 cartas?', purpose: 'drawOffer' })) g.draw(o, 2); }, ai: () => 1 });
def('Thought Wave Machine', { es: 'Lanza una moneda hasta que salga cruz. Por cada cara, devuelve una Energía unida al Pokémon Activo de tu rival a su mano. Tu turno termina (no puedes atacar).', can: (g, p) => g.opp(p).active && g.opp(p).active.energy.length > 0, play: async (g, p) => { const o = g.opp(p); const h = await g.flipUntilTails(p, 'Máquina de Ondas Mentales'); const t = o.active; for (let i = 0; i < h && t.energy.length; i++) { const c = t.energy.pop(); delete c.inPlay; o.hand.push(c); } g.log(`Devuelve ${Math.min(h, h)} Energía(s) a la mano del rival. El turno termina.`); p.turnOver = true; p.forceEnd = true; }, ai: () => 0 });
def('Time Capsule', { es: 'Tu rival puede barajar en su mazo 5 Pokémon y/o Energías básicas de su descarte. Luego tú puedes hacer lo mismo. No puedes jugar más Entrenadores este turno.', play: async (g, p) => { for (const pl of [g.opp(p), p]) { const opts = pl.discard.filter(c => isPk(g, c) || g.isBasicEnergy(c)); if (!opts.length) continue; const sel = await g.ask(pl, { kind: 'cards', title: 'Cápsula del Tiempo: elige hasta 5 cartas', cards: opts, min: 0, max: Math.min(5, opts.length), purpose: 'getAny' }); for (const c of sel) { g.removeFrom(pl.discard, c); pl.deck.push(c); } g.shuffleDeck(pl); } noMore(g, p); }, ai: (g, p) => p.deck.length < 12 ? 5 : 0 });
// Energías especiales
